package com.pawsshop.web;
import com.pawsshop.model.*; import com.pawsshop.repo.*; import com.pawsshop.service.SaleService; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api") public class ApiController {
 private final PetRepository pets; private final CustomerRepository customers; private final ProductRepository products; private final AppointmentRepository appointments; private final SaleRepository sales; private final ShopUserRepository users; private final SaleService saleService; private final PasswordEncoder encoder;
 public ApiController(PetRepository p,CustomerRepository c,ProductRepository pr,AppointmentRepository a,SaleRepository s,ShopUserRepository u,SaleService ss,PasswordEncoder e){pets=p;customers=c;products=pr;appointments=a;sales=s;users=u;saleService=ss;encoder=e;}
 @GetMapping("/me") public ShopUser me(Authentication auth){return users.findByUsername(auth.getName()).orElseThrow();}
 private void required(String s,String field){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException(field+" is required");}
 @GetMapping("/pets") public List<Pet> pets(){return pets.findAll();}
 @PostMapping("/pets") public Pet addPet(@RequestBody Pet x){validatePet(x);x.setId(null);return pets.save(x);}
 @PutMapping("/pets/{id}") public Pet updatePet(@PathVariable Long id,@RequestBody Pet x){validatePet(x);Pet old=pets.findById(id).orElseThrow(()->new IllegalArgumentException("Pet not found"));if(!old.getClass().equals(x.getClass()))throw new IllegalArgumentException("Pet type cannot be changed; create a new record instead");if(x.getOwnerId()==null)x.setOwnerId(old.getOwnerId());if(x.getWeight()==null)x.setWeight(old.getWeight());if(x.getMedicalNotes()==null)x.setMedicalNotes(old.getMedicalNotes());x.setId(id);return pets.save(x);}
 @DeleteMapping("/pets/{id}") public void deletePet(@PathVariable Long id){pets.deleteById(id);}
 private void validatePet(Pet x){required(x.getName(),"Pet name");if(x.getAge()!=null&&x.getAge()<0)throw new IllegalArgumentException("Age cannot be negative");}
 @GetMapping("/customers") public List<Customer> customers(){return customers.findAll();}
 @PostMapping("/customers") public Customer addCustomer(@RequestBody Customer x){required(x.getName(),"Customer name");x.setId(null);return customers.save(x);}
 @PutMapping("/customers/{id}") public Customer updateCustomer(@PathVariable Long id,@RequestBody Customer x){required(x.getName(),"Customer name");if(!customers.existsById(id))throw new IllegalArgumentException("Customer not found");x.setId(id);return customers.save(x);}
 @DeleteMapping("/customers/{id}") public void deleteCustomer(@PathVariable Long id){customers.deleteById(id);}
 @GetMapping("/products") public List<Product> products(){return products.findAll();}
 @PostMapping("/products") public Product addProduct(@RequestBody Product x){validateProduct(x);x.setId(null);return products.save(x);}
 @PutMapping("/products/{id}") public Product updateProduct(@PathVariable Long id,@RequestBody Product x){validateProduct(x);Product old=products.findById(id).orElseThrow(()->new IllegalArgumentException("Product not found"));if(!old.getClass().equals(x.getClass()))throw new IllegalArgumentException("Product type cannot be changed; create a new record instead");x.setId(id);return products.save(x);}
 @DeleteMapping("/products/{id}") public void deleteProduct(@PathVariable Long id){products.deleteById(id);}
 private void validateProduct(Product x){required(x.getName(),"Product name");if(x.getPrice()==null||x.getPrice().compareTo(BigDecimal.ZERO)<0||x.getPrice().scale()>2||x.getStock()<0)throw new IllegalArgumentException("Enter a non-negative price (maximum two decimals) and stock");}
 @GetMapping("/appointments") public List<Appointment> appointments(){return appointments.findAll();}
 @PostMapping("/appointments") public Appointment addAppointment(@RequestBody Appointment x){validateAppointment(x);x.setId(null);if(x.getStatus()==null)x.setStatus("BOOKED");return appointments.save(x);}
 @PutMapping("/appointments/{id}") public Appointment updateAppointment(@PathVariable Long id,@RequestBody Appointment x){validateAppointment(x);Appointment old=appointments.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found"));if(x.getOwnerId()==null)x.setOwnerId(old.getOwnerId());if(x.getPetId()==null)x.setPetId(old.getPetId());if(x.getServiceId()==null)x.setServiceId(old.getServiceId());if(x.getDoctorId()==null)x.setDoctorId(old.getDoctorId());if(x.getConsultationNotes()==null)x.setConsultationNotes(old.getConsultationNotes());new com.pawsshop.service.AppointmentWorkflow().validateTransition(old.getStatus(),x.getStatus());x.setId(id);return appointments.save(x);}
 @PatchMapping("/appointments/{id}/cancel") public Appointment cancel(@PathVariable Long id){Appointment x=appointments.findById(id).orElseThrow(()->new IllegalArgumentException("Appointment not found"));new com.pawsshop.service.AppointmentWorkflow().validateTransition(x.getStatus(),"CANCELLED");x.setStatus("CANCELLED");return appointments.save(x);}
 private void validateAppointment(Appointment x){if(x.getDoctorId()!=null&&!(users.findById(x.getDoctorId()).orElse(null) instanceof Doctor))throw new IllegalArgumentException("Doctor not found");required(x.getPetName(),"Pet name");required(x.getCustomerName(),"Customer name");required(x.getService(),"Service");required(x.getDate(),"Date");required(x.getTime(),"Time");try{java.time.LocalDate.parse(x.getDate());java.time.LocalTime.parse(x.getTime());}catch(Exception e){throw new IllegalArgumentException("Enter a valid date and time");}if(x.getStatus()!=null&&!Arrays.asList("BOOKED","PENDING","CONFIRMED","CANCELLED","COMPLETED").contains(x.getStatus()))throw new IllegalArgumentException("Invalid appointment status");}
 @GetMapping("/sales") public List<Sale> sales(){List<Sale> list=sales.findAll();Collections.reverse(list);return list;}
 @PostMapping("/sales") public Sale sale(@RequestBody SaleService.Request x){return saleService.create(x);}
 @GetMapping("/summary") public Map<String,Object> summary(){Map<String,Object> m=new LinkedHashMap<>();m.put("pets",pets.count());m.put("customers",customers.count());m.put("products",products.count());m.put("appointments",appointments.findAll().stream().filter(a->Arrays.asList("BOOKED","PENDING","CONFIRMED").contains(a.getStatus())).count());m.put("lowStock",products.findAll().stream().filter(p->p.getStock()<=5).count());m.put("salesCount",sales.count());m.put("revenue",sales.findAll().stream().map(Sale::getTotal).reduce(BigDecimal.ZERO,BigDecimal::add));return m;}
 public static class UserRequest {public String username;public String password;public String fullName;public String role;public String email;public String phone;public String specialization;}
 @GetMapping("/users") public List<ShopUser> users(){return users.findAll();}
 @PostMapping("/users") public ShopUser createUser(@RequestBody UserRequest x){required(x.username,"Username");required(x.password,"Password");required(x.fullName,"Name");if(x.password.length()<6)throw new IllegalArgumentException("Password must be at least 6 characters");if(users.findByUsername(x.username).isPresent())throw new IllegalArgumentException("Username already exists");ShopUser u;if("ADMIN".equals(x.role))u=new Admin();else if("STAFF".equals(x.role))u=new Staff();else if("CUSTOMER".equals(x.role))u=new CustomerAccount();else if("DOCTOR".equals(x.role)){Doctor d=new Doctor();d.setSpecialization(x.specialization);u=d;}else throw new IllegalArgumentException("Invalid role");u.setUsername(x.username.trim());u.setFullName(x.fullName);u.setEmail(x.email);u.setPhone(x.phone);u.setPasswordHash(encoder.encode(x.password));return users.save(u);}
 @PutMapping("/users/{id}") public ShopUser updateUser(@PathVariable Long id,@RequestBody UserRequest x){ShopUser u=users.findById(id).orElseThrow(()->new IllegalArgumentException("User not found"));required(x.username,"Username");required(x.fullName,"Name");String name=x.username.trim();users.findByUsername(name).filter(other->!other.getId().equals(id)).ifPresent(other->{throw new IllegalArgumentException("Username already exists");});if(x.role!=null&&!u.getRole().equals(x.role))throw new IllegalArgumentException("Account role cannot be changed; create a new account instead");if(x.password!=null&&!x.password.isEmpty()){if(x.password.length()<6)throw new IllegalArgumentException("Password must be at least 6 characters");u.setPasswordHash(encoder.encode(x.password));}u.setUsername(name);u.setFullName(x.fullName);u.setEmail(x.email);u.setPhone(x.phone);if(u instanceof Doctor)((Doctor)u).setSpecialization(x.specialization);return users.save(u);}
 @DeleteMapping("/users/{id}") public void deleteUser(@PathVariable Long id,Authentication auth){ShopUser u=users.findById(id).orElseThrow(()->new IllegalArgumentException("User not found"));if(u.getUsername().equals(auth.getName()))throw new IllegalArgumentException("You cannot delete your own account");users.delete(u);}
 @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,String>> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Collections.singletonMap("message",e.getMessage()));}
}
